FALLBACK_ENABLED = True


def gemini_generate(prompt, timeout=60):
    api_key = os.environ.get('GEMINI_API_KEY')
    if not api_key:
        raise RuntimeError('GEMINI_API_KEY is not configured in this Windows session.')
    url = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.6-flash:generateContent?key=' + api_key
    payload = json.dumps({'contents': [{'parts': [{'text': prompt}]}]}).encode('utf-8')

    last_error = None
    for attempt in range(3):
        request = urllib.request.Request(url, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:
                data = json.loads(response.read().decode('utf-8'))
            candidates = data.get('candidates', [])
            if not candidates:
                raise RuntimeError('Gemini returned no response candidates.')
            parts = candidates[0].get('content', {}).get('parts', [])
            text_parts = [part.get('text', '') for part in parts if part.get('text')]
            if not text_parts:
                raise RuntimeError('Gemini returned an empty response.')
            return ''.join(text_parts)
        except urllib.error.HTTPError as e:
            detail = e.read().decode('utf-8', errors='replace')
            last_error = RuntimeError(f'Gemini API error {e.code}: {detail[:500]}')
            if e.code not in (429, 500, 502, 503, 504) or attempt == 2:
                raise last_error from e
        except urllib.error.URLError as e:
            last_error = RuntimeError(f'Unable to reach Gemini API: {e.reason}')
            if attempt == 2:
                raise last_error from e
        except Exception as e:
            last_error = e
            if attempt == 2:
                raise

        import time
        time.sleep(1.5 * (attempt + 1))

    raise last_error or RuntimeError('Gemini request failed.')


def local_fallback_analysis(complaint):
    '''Lightweight deterministic fallback used only when Gemini is unavailable.
    It is intentionally transparent and is NOT presented as LLM output.
    '''
    text = complaint.lower()

    category_rules = [
        ('Security/Fraud', ['fraud','unauthorized','unauthorised','stolen','scam','hack','hacked','suspicious transaction','never made','unknown transaction','someone accessed']),
        ('Account Access', ['login','log in','password','locked out','cannot access',"can't access",'unable to access','otp','one time password']),
        ('Payment/Transfer Issue', ['transfer','payment','upi','transaction','beneficiary','recipient','money deducted','money debited','not received','pending payment']),
        ('Billing/Charges', ['fee','fees','charge','charged','billing','service fee','hidden fee','commission','overcharged']),
        ('Technical Issue', ['app crashed','crash','crashing','error','bug','not working','website down','technical','server']),
        ('Process/Verification', ['verification','kyc','verify','verification pending','document verification','onboarding']),
        ('Delivery/Timeline', ['delivery','delayed','delay','pending for','waiting','late','days','timeline']),
        ('Documentation', ['document','statement','certificate','receipt','paperwork']),
        ('Pricing', ['price','pricing','rate','interest rate','cost','expensive']),
        ('Customer Service', ['support','customer service','agent','representative','helpline','nobody helped','no response','complaint'])
    ]
    category = 'Customer Service'
    best_score = 0
    for name, words in category_rules:
        score = sum(1 for w in words if w in text)
        if score > best_score:
            category, best_score = name, score

    negative_words = ['angry','unhappy','disappointed','terrible','unacceptable','frustrated','awful','worst','never','failed','failure','problem','issue','scam','fraud','cannot',"can't",'not working','delayed','pending']
    positive_words = ['thank','thanks','happy','satisfied','good','great','resolved']
    neg = sum(1 for w in negative_words if w in text)
    pos = sum(1 for w in positive_words if w in text)
    sentiment = 'NEGATIVE' if neg > pos else ('POSITIVE' if pos > neg else 'NEUTRAL')

    critical_terms = ['fraud','unauthorized','unauthorised','stolen','hacked','security','never made','account accessed']
    high_terms = ['money deducted','money debited','not received','pending','failed','locked out','urgent','multiple times','days','complaint']
    if any(w in text for w in critical_terms):
        priority = 'CRITICAL'
    elif any(w in text for w in high_terms) or neg >= 3:
        priority = 'HIGH'
    elif neg >= 1 or best_score >= 1:
        priority = 'MEDIUM'
    else:
        priority = 'LOW'

    issue_map = {
        'Security/Fraud':'Potential unauthorized or suspicious account activity requires investigation.',
        'Account Access':'The customer is experiencing difficulty accessing the account or authentication process.',
        'Payment/Transfer Issue':'A payment or transfer appears to be delayed, failed, or not received as expected.',
        'Billing/Charges':'The customer is questioning a charge, fee, commission, or billing amount.',
        'Technical Issue':'The customer reports a technical problem affecting a financial service or application.',
        'Process/Verification':'The customer is experiencing a verification, KYC, or process-related delay.',
        'Delivery/Timeline':'The customer is concerned about a delay or service timeline.',
        'Documentation':'The customer needs or has an issue with financial documentation or records.',
        'Pricing':'The customer is raising a concern about pricing, rates, or cost.',
        'Customer Service':'The complaint primarily concerns support, communication, or service handling.'
    }
    action_map = {
        'Security/Fraud':'Verify the transaction and secure the customer account. Escalate for fraud review where appropriate.',
        'Account Access':'Verify the customer identity and investigate the authentication/access issue. Provide a secure recovery path.',
        'Payment/Transfer Issue':'Check the transaction status and reconciliation trail. Resolve or communicate the expected completion timeline.',
        'Billing/Charges':'Review the charge against the applicable fee schedule. Explain the charge clearly and correct it if it was applied incorrectly.',
        'Technical Issue':'Review application/service logs and reproduce the issue if possible. Provide a workaround or resolution update to the customer.',
        'Process/Verification':'Check the verification workflow and identify the pending step. Provide the customer with the next required action or status update.',
        'Delivery/Timeline':'Review the service timeline and current status. Communicate a realistic resolution or delivery update.',
        'Documentation':'Check the requested record and documentation process. Provide the correct document or explain the required steps.',
        'Pricing':'Review the applicable pricing or rate. Explain the basis clearly and correct any inaccurate charge or quote.',
        'Customer Service':'Review the previous support interactions and assign ownership. Provide a clear response and resolution path.'
    }

    root_cause_map = {
        'Security/Fraud':'Potential unauthorized access or transaction activity indicated by the complaint.',
        'Account Access':'Potential authentication, credential or account-access problem.',
        'Payment/Transfer Issue':'Potential payment processing, settlement, beneficiary or transaction-status issue.',
        'Billing/Charges':'Potential unexpected fee, charge or billing communication issue.',
        'Technical Issue':'Potential application, system or technical-service failure.',
        'Process/Verification':'Potential delay or issue in verification, KYC or onboarding workflow.',
        'Delivery/Timeline':'Potential processing or service-timeline delay.',
        'Documentation':'Potential document, statement or record-generation issue.',
        'Pricing':'Potential pricing, rate or cost-related concern.',
        'Customer Service':'Potential service-response, communication or support-process issue.'
    }
    resolution_map = {
        'Security/Fraud':'Verify the transaction or access event, secure the account where appropriate, and route the case through the fraud/security process.',
        'Account Access':'Verify the customer and access status, restore access using the approved process, and confirm the customer can log in securely.',
        'Payment/Transfer Issue':'Trace the transaction reference and status, verify settlement or reversal, and communicate the outcome to the customer.',
        'Billing/Charges':'Verify the charge against the applicable fee schedule, correct any inappropriate charge, and explain the outcome clearly.',
        'Technical Issue':'Check the relevant system or application status, reproduce the issue if possible, and provide a workaround or fix.',
        'Process/Verification':'Check the case and required documents, identify the workflow bottleneck, and complete or restart the verification step as appropriate.',
        'Delivery/Timeline':'Check the current processing stage, identify the delay, provide a realistic timeline, and complete the pending service action.',
        'Documentation':'Verify the requested record, correct missing or inaccurate information, and provide the document through the approved channel.',
        'Pricing':'Verify the applicable price or rate, correct any discrepancy, and explain the basis of the charge or rate.',
        'Customer Service':'Review the interaction history, assign ownership to the appropriate support team, and provide a clear response and resolution path.'
    }
    escalation_map = {
        'Security/Fraud':'Fraud / Security Operations',
        'Account Access':'Digital Banking / Access Support',
        'Payment/Transfer Issue':'Payments Operations',
        'Billing/Charges':'Billing / Customer Service',
        'Technical Issue':'Technology / Application Support',
        'Process/Verification':'KYC / Operations',
        'Delivery/Timeline':'Operations / Service Delivery',
        'Documentation':'Records / Operations',
        'Pricing':'Product / Pricing Operations',
        'Customer Service':'Customer Service Operations'
    }
    return {
        'category': category,
        'sentiment': sentiment,
        'priority': priority,
        'key_issue': issue_map[category],
        'business_action': action_map[category],
        'root_cause': root_cause_map[category],
        'recommended_resolution': resolution_map[category],
        'escalation_recommendation': escalation_map[category],
        'resolution_status': 'New'
    }


def fallback_record(complaint):
    r = local_fallback_analysis(complaint)
    return {
        'timestamp': datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
        'complaint': complaint,
        'category': r['category'],
        'sentiment': r['sentiment'],
        'priority': r['priority'],
        'key_issue': r['key_issue'],
        'business_action': r['business_action'],
        'root_cause': r.get('root_cause','Likely cause identified from complaint context; verify with the responsible team.'),
        'recommended_resolution': r.get('recommended_resolution','Review the case, verify the underlying transaction/process, and complete the appropriate customer resolution.'),
        'escalation_recommendation': r.get('escalation_recommendation','Route to the relevant operations team if the issue remains unresolved or requires specialist review.'),
        'resolution_status': 'New'
    }

def parse_single_result(text, complaint):
    result = {}
    for line in text.strip().split('\n'):
        if ':' in line:
            k,v=line.split(':',1); result[k.strip().lower()]=v.strip()
    return {
        'timestamp':datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
        'complaint':complaint,
        'category':result.get('category','Unknown'),
        'sentiment':result.get('sentiment','Unknown'),
        'priority':result.get('priority','Unknown'),
        'key_issue':result.get('key issue','Unknown'),
        'business_action':result.get('business action','Unknown'),
        'root_cause':result.get('root cause','Unknown'),
        'recommended_resolution':result.get('recommended resolution','Unknown'),
        'escalation_recommendation':result.get('escalation recommendation','Unknown'),
        'resolution_status':result.get('resolution status','New')
    }

def gemini_health_check():
    return gemini_generate('Reply with exactly: FINOVA_AI_OK', timeout=15).strip() == 'FINOVA_AI_OK'


