st.markdown(f'''<div class="top"><div class="brand"><div class="mark">◆</div>FINOVA AI</div><div style="display:flex;align-items:center;gap:18px"><div style="font-size:11px;color:#8d97a8">Dashboard &nbsp;&nbsp; Settings &nbsp;&nbsp; Help & Support</div><div class="status"><span class="dot"></span>AI system active · {len(st.session_state.analyzed_complaints)} stored</div></div></div>''',unsafe_allow_html=True)
